const pais = typeof p.pais === "string" ? p.pais.trim() : "";
if (!ciudad || !pais || ciudad.length > 80 || pais.length > 80) {
 msg.statusCode=400; msg.payload={error:"Ingrese ciudad y país (máximo 80 caracteres)."};
} else {
 flow.set("camila_ubicacion", {ciudad,pais});
 msg.statusCode=200; msg.payload={ciudad,pais,mensaje:"Ubicación guardada: " + ciudad + ", " + pais + ". Pulse Consultar ciudad y país."};
}
return msg;
````
